// Per-conversation memory (survives between messages via workflow static data).
// Single source of truth: staticData.chats['chat_<id>'] — Prepare AND Resolve
// both read/write this map (previously they used two different maps, so
// collected info never actually persisted across turns).
const msg = $input.first().json.message;
if (!msg || !msg.text) return []; // ignore stickers/photos for the demo
const chatId = msg.chat.id;
const text = String(msg.text).trim();
const from = msg.from?.first_name || 'Parent';

const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};
const key = 'chat_' + chatId;
const state = staticData.chats[key] || { data: {}, history: [], lang: 'en' };

// Quick commands skip the AI turn entirely.
const cmd = text === '/start' ? '/start' : (text === '/stop' ? '/stop' : (text === '/help' ? '/help' : null));
if (cmd) {
  return [{ json: { quick: 'quick', quickCommand: cmd, chatId, key } }];
}

// Track activity (nudge logic skips chats active in the last 2h) + language.
state.lastActiveAt = new Date().toISOString();
const isVi = /[ăâđêôơưàáảãạầấẩẫậằắẳẵặèéẻẽẹềếểễệìíỉĩịòóỏõọồốổỗộùúủũụỳýỷỹỵ]/i.test(text);
if (isVi) state.lang = 'vi';

state.history = state.history || [];
state.history.push({ role: 'parent', text });
while (state.history.length > 8) state.history.shift();
staticData.chats[key] = state;

// --- system prompt OWNED BY PROMPTLEDGER (n8n/parent-chat-assistant): fetched
// live on every turn so promoting a new version changes behavior on the next
// parent message. Fail-open per the unattended policy: last-known-good from
// workflow static data, else the committed copy below; item is tagged.
const PROMPT_APP = "n8n";
const PROMPT_NAME = "parent-chat-assistant";
const COMMITTED_PROMPT = "You are the friendly enrollment assistant of an English training school, chatting with parents on Telegram.\nKnowledge base:\nCourses: IELTS Preparation (intensive & standard), TOEFL Preparation, Business English.\nClass size: max 12 students. Teachers are certified, IELTS 8.0+.\nFree placement test every Saturday morning.\nTuition: from 6,000,000 VND for an 8-week course (exact quote given by a counselor).\nCampuses: District 1 and Thu Duc (Ho Chi Minh City).\nHours: 8:00-20:00 Mon-Sat. Hotline: 0900 000 000.\n\nRules:\n- Answer questions clearly and briefly, using ONLY the knowledge base. If something is not there, say a counselor will confirm it.\n- When the parent shows enrollment intent (wants to register, asks how to sign up), collect: full name, phone number, and course of interest. Ask for ONE missing item at a time, warmly.\n- Never invent prices beyond the \"from 6,000,000 VND\" line. Never promise discounts or schedules.\n- Reply in the parent's language (Vietnamese or English).\n- In the submit confirmation, mention the phone number at most once and keep a consistent, warm tone.\nReturn ONLY a single JSON object:\n- Normal answer or still collecting: {\"action\":\"reply\",\"text\":\"<your reply>\",\"collected\":{...}}\n- When name AND phone AND course are all known: {\"action\":\"submit\",\"text\":\"<warm confirmation that a counselor will contact them soon>\",\"lead\":{\"name\":\"...\",\"phone\":\"...\",\"course\":\"...\",\"note\":\"<anything else the parent said that matters>\"}}";

function registryUrl(path) {
  const baseUrl = ($env.PROMPTLEDGER_URL || 'http://localhost:4747').replace(/\/+$/, '');
  return baseUrl.replace('//localhost:', '//127.0.0.1:') + path;
}

// Fail-open contract: fetchLive NEVER throws. Primary = global fetch
// (Node 18+ n8n runtime); 3s timeout; every failure resolves ok:false.
async function fetchLive() {
  const apiKey = $env.PROMPTLEDGER_API_KEY || '';
  if (!apiKey) return { ok: false, error: 'PROMPTLEDGER_API_KEY not set in n8n environment' };
  try {
    const res = await fetch(registryUrl('/api/prompts/' + PROMPT_APP + '/' + PROMPT_NAME + '/live'), {
      headers: { 'x-api-key': apiKey },
      signal: AbortSignal.timeout(3000)
    });
    const json = await res.json();
    if (res.ok && typeof json.text === 'string' && json.text.trim() && typeof json.version === 'number') {
      return { ok: true, text: json.text, version: json.version };
    }
    if (res.status === 404) return { ok: false, error: 'no live version of ' + PROMPT_APP + '/' + PROMPT_NAME + ' (404)' };
    if (res.status === 401 || res.status === 403) return { ok: false, error: 'registry rejected the API key (HTTP ' + res.status + ')' };
    return { ok: false, error: 'registry returned HTTP ' + res.status };
  } catch (e) {
    const msg = String((e && e.message) || e);
    return { ok: false, error: msg.toLowerCase().includes('timeout') || msg.toLowerCase().includes('abort') ? 'registry timeout after 3000ms' : msg };
  }
}
// n8n persists static data between executions of ACTIVE workflows - our
// last-known-good store. (Manual test runs do not persist it; the
// committed copy covers that case.)
// staticData was already declared above (conversation memory) - same global object.
const promptCache = staticData.promptCache = staticData.promptCache || {};
const live = await fetchLive();
let system, promptSource, promptVersion = null, promptError = null;
if (live.ok) {
  system = live.text;
  promptVersion = live.version;
  promptSource = 'live v' + live.version;
  promptCache.text = live.text;
  promptCache.version = live.version;
  promptCache.at = new Date().toISOString();
} else {
  promptError = live.error;
  if (promptCache.text) {
    system = promptCache.text;
    promptVersion = promptCache.version;
    promptSource = 'fallback-cached v' + (promptCache.version || '?');
  } else {
    system = COMMITTED_PROMPT;
    promptSource = 'fallback-committed';
  }
  console.error('[promptledger] live fetch failed (' + promptError + ') - serving ' + promptSource + ' for ' + PROMPT_APP + '/' + PROMPT_NAME + '; processing continues');
}

const user = [
  'Collected so far: ' + JSON.stringify(state.data || {}),
  'Recent conversation:',
  ...state.history.map((h) => h.role + ': ' + h.text)
].join('\n');

return [{ json: { chatId, from, text, key, state, system, user, prompt_source: promptSource, prompt_version: promptVersion, prompt_error: promptError } }];

// /stop and /start flip the CRM opt-out flag; /help is informational only.
// Reversibility: /start re-enables nudges (explicit re-consent), but the
// lifetime cap (max 2 automated touches per lead) is NEVER reset.
const item = $input.first().json;
const cmd = item.quickCommand;
const chatId = item.chatId;

const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};
const key = 'chat_' + chatId;

let replyText = '';
let flagChange = null;

if (cmd === '/stop') {
  if (staticData.chats[key]) staticData.chats[key].stopped = true;
  flagChange = { telegram_stopped: true };
  replyText = 'No problem — I won\'t send you any more check-ins. You can still ask me anything anytime, and just say /start to turn follow-ups back on.';
} else if (cmd === '/start') {
  if (staticData.chats[key]) staticData.chats[key].stopped = false;
  flagChange = { telegram_stopped: false };
  replyText = [
    'Hi! I\'m the enrollment assistant for our English courses. 👋',
    'Ask me anything about IELTS, TOEFL or Business English — tuition, schedules, the free Saturday placement test — or just tell me which course you\'re interested in and I\'ll help you register.',
    '(Mình có thể trò chuyện bằng tiếng Việt nhé!)'
  ].join('\n');
} else { // /help
  replyText = [
    'Here\'s what I can do:',
    '• Answer questions about courses, tuition and schedules',
    '• Register you for a course (I\'ll just need a name, phone and course choice)',
    '• /start — restart the conversation and re-enable follow-ups',
    '• /stop — stop follow-up check-ins anytime'
  ].join('\n');
}

return [{ json: { chatId, replyText, flagChange } }];

// Schema check + merge AI's collected info into conversation state.

// PromptLedger run trace (fire-and-forget): records which prompt version
// served this call plus the model, latency, and outcome. NEVER throws and
// never blocks the response - telemetry must not break a lead or a chat.
function traceRun(body) {
  const url = ($env.PROMPTLEDGER_URL || '').replace(/\/+$/, '');
  if (!url) return;
  fetch(url + '/api/runs', {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...($env.PROMPTLEDGER_API_KEY ? { 'x-api-key': $env.PROMPTLEDGER_API_KEY } : {})
    },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(5000)
  }).then(
    (r) => { if (!r.ok) console.error('[runtrace] PromptLedger rejected run trace (HTTP ' + r.status + ')'); },
    (e) => console.error('[runtrace] run trace failed (continuing): ' + String(e))
  );
}
const turn = $('Prepare turn').first().json;
const ai = $('AI chat turn').first().json;

const text = (ai.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  traceRun({ name: 'parent-chat-assistant', prompt_version: turn.prompt_version, prompt_source: turn.prompt_source, model: ai.modelVersion || null, input: turn.user, output: text, latency_ms: null, ok: false, error: 'AI response was not valid JSON: ' + e.message });
  return [{ json: { chatId: turn.chatId, action: 'reply', replyText: 'Sorry, I had trouble just now — please try again in a moment.' } }];
}

const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};
const state = staticData.chats[turn.key] || { data: {}, history: [], lang: 'en' };
state.data = { ...(state.data || {}), ...(parsed.collected || {}) };

let action = parsed.action === 'submit' ? 'submit' : 'reply';
const lead = parsed.lead || {};
// Only submit when we truly have the required trio.
if (action === 'submit' && (!lead.name || !lead.phone || !lead.course)) {
  action = 'reply';
}

if (action === 'submit') {
  // Reset collection, but keep language + opt-out + activity markers.
  staticData.chats[turn.key] = {
    data: {},
    history: [],
    lang: state.lang || 'en',
    stopped: state.stopped || false,
    lastActiveAt: state.lastActiveAt
  };
} else {
  staticData.chats[turn.key] = state;
}

const replyText = action === 'submit'
  ? (parsed.text || `Thank you, ${lead.name}! Your registration for ${lead.course} is in — a counselor will call ${lead.phone} soon to finalize everything.`)
  : (parsed.text || 'Could you tell me a bit more?');

traceRun({ name: 'parent-chat-assistant', prompt_version: turn.prompt_version, prompt_source: turn.prompt_source, model: ai.modelVersion || null, input: turn.user, output: text, latency_ms: null, ok: true, error: null });
return [{ json: {
  chatId: turn.chatId,
  action,
  replyText,
  lead: action === 'submit'
    ? {
        name: String(lead.name).slice(0, 200),
        phone: String(lead.phone).slice(0, 40),
        course: String(lead.course).slice(0, 100),
        note: String(lead.note || turn.text).slice(0, 1000),
        from: turn.from
      }
    : null
} }];

// R-04 sender side - HMAC-sign the pipeline payload. Matches the verifier
// in admissions-lead-pipeline.json (commit 3133f39): signature =
// HMAC-SHA256 over `${timestamp}.${JSON.stringify(payload)}`, hex-encoded.
const crypto = require('node:crypto');
const item = $input.first().json;
const lead = item.lead || {};
const payload = {
  name: lead.name,
  email: String(lead.phone || '').replace(/\D/g, '') + '.tg@lead.local',
  phone: lead.phone,
  source: 'telegram',
  telegram_chat_id: String(item.chatId),
  course_interest: lead.course,
  message: '[Telegram chat with ' + lead.from + '] ' + lead.note
};
const ts = Date.now();
const signature = crypto
  .createHmac('sha256', $env.N8N_WEBHOOK_SECRET)
  .update(ts + '.' + JSON.stringify(payload))
  .digest('hex');
return [{ json: { signedBody: JSON.stringify({ timestamp: ts, signature, payload }) } }];

// Follow-up nudge picker (Tier 2 nurture / Tier 3 re-engagement).
// Caps: max 2 automated touches per lead, EVER (nudges_sent survives /start
// re-enable). telegram_stopped is filtered server-side; the static flag is
// re-checked for pre-lead chats. Chats active in the last 2h are skipped.
const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};
const now = Date.now();
const out = [];

const T2 = {
  en: [
    'Just checking in — have you had a chance to speak with one of our advisors yet? Happy to answer any questions about schedules or tuition if anything is unclear.',
    'Hi again! Your registration is still on our list — an advisor will reach out shortly. In the meantime, any questions I can answer for you?'
  ],
  vi: [
    'Chào anh/chị, mình theo lại câu hỏi hôm trước — anh/chị đã trao đổi với chuyên viên tư vấn của chúng tôi chưa? Nếu cần thông tin thêm về lịch học hay học phí, cứ nhắn mình nhé!',
    'Chào anh/chị! Đăng ký của anh/chị vẫn đang trong danh sách của chúng tôi — chuyên viên sẽ sớm liên hệ. Trong lúc chờ, anh/chị cần mình giải đáp gì thêm không?'
  ]
};
const T3 = {
  en: [
    'A small update: we have a free trial class running this month for IELTS/TOEFL — would you like to reserve a spot? If you\'ve already decided, feel free to ignore this, and thank you for your interest!',
    'Last check-in from me, promise 🙂 We still have a seat reserved for you in the upcoming IELTS course. Still interested? One reply is all it takes — or just say /stop and I won\'t message again.'
  ],
  vi: [
    'Một tin nhỏ: tháng này chúng tôi có buổi học thử miễn phí cho lớp IELTS/TOEFL — anh/chị có muốn giữ chỗ không? Nếu đã quyết định rồi thì bỏ qua tin nhắn này nhé, cảm ơn anh/chị đã quan tâm!',
    'Lần nhắc cuối cùng của mình, hứa 🙂 Chúng tôi vẫn giữ một chỗ cho anh/chị trong lớp IELTS sắp khai giảng. Vẫn quan tâm chứ ạ? Chỉ cần một tin nhắn trả lời — hoặc nhắn /stop để mình ngừng nhắc.'
  ]
};

for (const lead of $input.all().map((i) => i.json)) {
  if (!lead.telegram_chat_id) continue;
  const chat = staticData.chats['chat_' + lead.telegram_chat_id] || {};
  if (chat.stopped) continue;
  const lastActive = chat.lastActiveAt ? Date.parse(chat.lastActiveAt) : 0;
  if (now - lastActive < 2 * 60 * 60 * 1000) continue; // mid-conversation
  const age = now - Date.parse(lead.created_at);
  const lang = chat.lang || 'en';
  const variant = Number(String(lead.id).slice(-1)) % 2; // rotate templates per lead
  let text = null;
  let tier = 0;
  if ((lead.nudges_sent || 0) === 0 && age >= 24 * 60 * 60 * 1000) {
    tier = 2;
    text = T2[lang][variant];
  } else if ((lead.nudges_sent || 0) === 1 && age >= 5 * 24 * 60 * 60 * 1000) {
    tier = 3;
    text = T3[lang][variant];
  }
  if (text) {
    out.push({ json: { leadId: lead.id, chatId: lead.telegram_chat_id, tier, nextCount: (lead.nudges_sent || 0) + 1, text } });
  }
}
return out;
